useEffect(() => {
  const c = new AbortController();
  fetch('/api/products',{signal:c.signal})
    .then(r=>{if(!r.ok) throw Error('Failed'); return r.json();})
    .then(data=>{if(!c.signal.aborted) setItems(data);})
    .catch(e=>{if(!c.signal.aborted) setError(e.message);});
  return ()=>c.abort();
},[]);
